orders.sync:
function (doc, oldDoc, meta) {
  // Offline-first orders and shopper actions. A shopper's phone may CREATE one, as itself,
  // as 'pending'. Only the backend (admin / import) may advance its status.
  if (doc._deleted) { requireAdmin(); if (oldDoc) { channel("shopper:" + oldDoc.shopper_id); } return; }
  if (!doc.shopper_id) { throw({forbidden: "shopper_id is required"}); }
  if (oldDoc == null || oldDoc._deleted) {
    requireUser(doc.shopper_id);
    if (doc.type !== "request") { throw({forbidden: "type must be 'request'"}); }
    if (doc.status !== "pending") { throw({forbidden: "new orders must be 'pending'"}); }
    if (doc._id.indexOf("order::" + doc.shopper_id + "::") !== 0) { throw({forbidden: "id must be order::<shopper_id>::<uuid>"}); }
  } else {
    if (oldDoc.shopper_id !== doc.shopper_id) { throw({forbidden: "shopper_id is immutable"}); }
    requireAdmin();
  }
  channel("shopper:" + doc.shopper_id);
}
